{"file_path":"src/nodes.js","content":"/**
 * The document model. Every node carries its own kind so that `keys` can name
 * a type and so that an integer and a whole float stay apart.
 */

export function table(origin) {
  // origin is 'header', 'dotted' or 'walk' for the tables a path creates on the
  // way through, and 'inline' for the ones a `{ ... }` value builds.
  return { kind: 'table', map: new Map(), origin, header: origin === 'header' }
}

export function arrayOfTables() {
  return { kind: 'atables', items: [] }
}

export function array(items) {
  return { kind: 'array', items }
}

export function scalar(kind, v) {
  return { kind, v }
}

/** The name of a node as `keys` reports it. */
export function typeName(node) {
  if (node.kind === 'table') return 'table'
  if (node.kind === 'atables' || node.kind === 'array') return 'array'
  return node.kind
}

/** A child path, written the way every message and every `keys` line writes it. */
export function childPath(prefix, key) {
  return prefix === '' ? key : `${prefix}.${key}`
}

export function indexPath(prefix, i) {
  return `${prefix}[${i}]`
}
"}

