{"file_path":"src/parse.js","content":"/**
 * The reader. One line at a time, it turns a configuration document into the
 * node tree of `nodes.js`, or throws the first `ConfError` it meets.
 */

import { table, arrayOfTables, array, scalar, childPath, indexPath } from './nodes.js'

export class ConfError extends Error {
  constructor(reason) {
    super(reason)
    this.reason = reason
  }
}

const NAME_CHARS = /[A-Za-z0-9_-]/

class Scanner {
  constructor(text) {
    this.text = text
    this.i = 0
  }

  get done() {
    return this.i >= this.text.length
  }

  peek(offset = 0) {
    return this.text[this.i + offset]
  }

  next() {
    return this.text[this.i++]
  }

  /** Spaces and tabs are the only run of nothing a line may hold. */
  space() {
    while (!this.done) {
      const c = this.peek()
      if (c !== ' ' && c !== '\t') break
      this.i += 1
    }
  }

  /** True where a comment would start, which is where the line ends. */
  atComment() {
    return !this.done && (this.peek() === '#' || this.peek() === ';')
  }

  /** True once nothing but a comment can be left. */
  atEnd() {
    return this.done || this.atComment()
  }
}

/** A name: a bare word, or a quoted string standing in for one. */
function readName(sc) {
  const c = sc.peek()
  if (c === '"') return readBasic(sc)
  if (c === "'") return readLiteral(sc)
  let out = ''
  while (!sc.done && NAME_CHARS.test(sc.peek())) out += sc.next()
  if (out === '') throw new ConfError('expected a name')
  return out
}

/** Names joined by dots, with spaces and tabs allowed around each dot. */
function readDottedName(sc) {
  const names = [readName(sc)]
  for (;;) {
    const mark = sc.i
    sc.space()
    if (sc.done || sc.peek() !== '.') {
      sc.i = mark
      return names
    }
    sc.i += 1
    sc.space()
    names.push(readName(sc))
  }
}

function readBasic(sc) {
  sc.i += 1
  let out = ''
  for (;;) {
    if (sc.done) throw new ConfError('unterminated string')
    const c = sc.next()
    if (c === '"') return out
    if (c !== '\\') {
      out += c
      continue
    }
    if (sc.done) throw new ConfError('unterminated string')
    const e = sc.next()
    if (e === '"') out += '"'
    else if (e === '\\') out += '\\'
    else if (e === 'n') out += '\n'
    else if (e === 't') out += '\t'
    else if (e === 'r') out += '\r'
    else if (e === '0') out += '\0'
    else if (e === 'u') {
      const hex = sc.text.slice(sc.i, sc.i + 4)
      if (!/^[0-9A-Fa-f]{4}$/.test(hex)) throw new ConfError('invalid escape \\u')
      sc.i += 4
      out += String.fromCharCode(parseInt(hex, 16))
    } else throw new ConfError(`invalid escape \\${e}`)
  }
}

function readLiteral(sc) {
  sc.i += 1
  let out = ''
  for (;;) {
    if (sc.done) throw new ConfError('unterminated string')
    const c = sc.next()
    if (c === "'") return out
    out += c
  }
}

const INTEGER = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/

/**
 * A bare value runs to whitespace or to the punctuation that closes it. A `#`
 * belongs to it, so a value that runs into one is invalid rather than trimmed.
 */
function readBareWord(sc) {
  let out = ''
  while (!sc.done) {
    const c = sc.peek()
    if (c === ' ' || c === '\t' || c === ',' || c === ']' || c === '}' || c === ';') break
    out += sc.next()
  }
  return out
}

function bareValue(text) {
  if (text === 'true') return scalar('boolean', true)
  if (text === 'false') return scalar('boolean', false)
  if (INTEGER.test(text)) return scalar('integer', BigInt(text.replace(/_/g, '')))
  if (FLOAT.test(text)) return scalar('float', Number(text.replace(/_/g, '')))
  throw new ConfError(`invalid value ${text}`)
}

/** A value, with `path` naming where it lands so that its own keys can be named. */
function readValue(sc, path) {
  if (sc.done || sc.atComment() || sc.peek() === ',' || sc.peek() === ']' || sc.peek() === '}') {
    throw new ConfError('expected a value')
  }
  const c = sc.peek()
  if (c === '"') return scalar('string', readBasic(sc))
  if (c === "'") return scalar('string', readLiteral(sc))
  if (c === '[') return readArray(sc, path)
  if (c === '{') return readInline(sc, path)
  return bareValue(readBareWord(sc))
}

function readArray(sc, path) {
  sc.i += 1
  const items = []
  for (;;) {
    sc.space()
    if (sc.done || sc.atComment()) throw new ConfError('unterminated array')
    if (sc.peek() === ']') {
      sc.i += 1
      return array(items)
    }
    items.push(readValue(sc, indexPath(path, items.length)))
    sc.space()
    if (sc.done || sc.atComment()) throw new ConfError('unterminated array')
    if (sc.peek() === ',') {
      sc.i += 1
      continue
    }
    if (sc.peek() === ']') {
      sc.i += 1
      return array(items)
    }
    throw new ConfError('trailing text after a value')
  }
}

function readInline(sc, path) {
  sc.i += 1
  const node = table('inline')
  sc.space()
  if (sc.done || sc.atComment()) throw new ConfError('unterminated inline table')
  if (sc.peek() === '}') {
    sc.i += 1
    return node
  }
  for (;;) {
    sc.space()
    if (sc.done || sc.atComment()) throw new ConfError('unterminated inline table')
    const names = readDottedName(sc)
    sc.space()
    if (sc.done || sc.peek() !== '=') throw new ConfError('expected = in an inline table')
    sc.i += 1
    sc.space()
    const target = assignPath(node, names, path)
    target.set(readValue(sc, target.path))
    sc.space()
    if (sc.done || sc.atComment()) throw new ConfError('unterminated inline table')
    if (sc.peek() === ',') {
      sc.i += 1
      continue
    }
    if (sc.peek() === '}') {
      sc.i += 1
      return node
    }
    throw new ConfError('trailing text after a value')
  }
}

/** The last element is where a walk through an array of tables goes. */
function step(node, key, path) {
  const found = node.map.get(key)
  if (found === undefined) {
    const made = table('walk')
    node.map.set(key, made)
    return made
  }
  if (found.kind === 'table') return found
  if (found.kind === 'atables' && found.items.length > 0) return found.items[found.items.length - 1]
  throw new ConfError(`${path} is not a table`)
}

/**
 * Walks the dots of an assignment and hands back the slot the last name names,
 * refusing a name that already holds anything.
 */
function assignPath(root, names, prefix) {
  let node = root
  let path = prefix
  for (let i = 0; i < names.length - 1; i += 1) {
    path = childPath(path, names[i])
    node = step(node, names[i], path)
    if (node.origin === 'walk') node.origin = 'dotted'
  }
  const key = names[names.length - 1]
  path = childPath(path, key)
  if (node.map.has(key)) throw new ConfError(`key ${path} is defined twice`)
  const holder = node
  return { path, set: (value) => holder.map.set(key, value) }
}

/** A `[name]` or `[[name]]` header, which chooses the table lines land in. */
function readHeader(sc, root) {
  sc.i += 1
  const isArray = !sc.done && sc.peek() === '['
  if (isArray) sc.i += 1
  sc.space()
  const names = readDottedName(sc)
  sc.space()
  if (sc.done || sc.peek() !== ']') throw new ConfError('unterminated table header')
  sc.i += 1
  if (isArray) {
    if (sc.done || sc.peek() !== ']') throw new ConfError('unterminated table header')
    sc.i += 1
  }
  sc.space()
  if (!sc.atEnd()) throw new ConfError('trailing text after a table header')

  let node = root
  let path = ''
  for (let i = 0; i < names.length - 1; i += 1) {
    path = childPath(path, names[i])
    node = step(node, names[i], path)
  }
  const key = names[names.length - 1]
  path = childPath(path, key)
  const found = node.map.get(key)
  if (isArray) {
    let holder = found
    if (holder === undefined) {
      holder = arrayOfTables()
      node.map.set(key, holder)
    } else if (holder.kind !== 'atables') {
      throw new ConfError(`${path} is not an array of tables`)
    }
    const fresh = table('header')
    holder.items.push(fresh)
    return { node: fresh, path: indexPath(path, holder.items.length - 1) }
  }
  if (found === undefined) {
    const made = table('header')
    node.map.set(key, made)
    return { node: made, path }
  }
  if (found.kind !== 'table') throw new ConfError(`${path} is not a table`)
  if (found.header) throw new ConfError(`table ${path} is defined twice`)
  found.header = true
  return { node: found, path }
}

/** Parses a whole document, throwing a `ConfError` carrying a line number. */
export function parse(text) {
  let lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = table('header')
  let current = root
  let currentPath = ''

  for (let n = 0; n < lines.length; n += 1) {
    const sc = new Scanner(lines[n])
    sc.space()
    if (sc.done || sc.atComment()) continue
    try {
      if (sc.peek() === '[') {
        const chosen = readHeader(sc, root)
        current = chosen.node
        currentPath = chosen.path
        continue
      }
      const names = readDottedName(sc)
      sc.space()
      if (sc.done || sc.peek() !== '=') throw new ConfError('expected key = value')
      sc.i += 1
      sc.space()
      const target = assignPath(current, names, currentPath)
      const value = readValue(sc, target.path)
      sc.space()
      if (!sc.atEnd()) throw new ConfError('trailing text after a value')
      target.set(value)
    } catch (err) {
      if (err instanceof ConfError) {
        err.line = n + 1
        throw err
      }
      throw err
    }
  }
  return root
}
"}

